-- SQLite seed for workshop1 (api/app/models.py).
-- Source: UCSD Google Local Reviews 2021, review-Alaska_10.json.gz.
-- The most-reviewed place in the file, selected with DuckDB:
--   gmap_id 0x56c897b9ce6000df:0xd707e127588a8c6c -> Moose's Tooth Pub & Pizzeria, Anchorage (2833 reviews).
-- Companion JSON: api/alaska_moose_tooth_reviews.json (same rows, plus owner responses).
--
-- Adaptations to this schema:
--   * The review file has no place metadata. Name and address were inferred from review text.
--   * gmap_id is not a Places API Place ID, so google_place_id = 'pending:gmap:<gmap_id>'
--     and no sync_targets row is created for it.
--   * google_rating = mean review stars (4.7); user_rating_count = 2833.
--   * reviews.text is NOT NULL: 1163 star-only reviews are stored as ''.
--   * external_review_id = UUIDv5(gmap_id|user_id|time), so the script is safe to re-run.
--   * published_at is the source epoch ms converted to UTC.
-- Reviews are inserted in batches of 250 rows instead of one statement per row
-- (2833 single-row upserts would make the file about 4x larger).
-- Requires tables already created (python api/seed.py or the app startup does that).
BEGIN;

INSERT INTO restaurants (google_place_id, name, address, google_rating, user_rating_count, last_synced_at, updated_at) VALUES
  ('pending:gmap:0x56c897b9ce6000df:0xd707e127588a8c6c', 'Moose''s Tooth Pub & Pizzeria', '3300 Old Seward Hwy, Anchorage, AK 99503, USA', 4.7, 2833, '2021-05-23 17:16:39', '2021-05-23 17:16:39')
ON CONFLICT(google_place_id) DO UPDATE SET
  name = excluded.name,
  address = excluded.address,
  google_rating = excluded.google_rating,
  user_rating_count = excluded.user_rating_count,
  last_synced_at = excluded.last_synced_at,
  updated_at = excluded.updated_at;

-- Reviews. restaurant_id is resolved from google_place_id so integer keys stay stable.
-- VALUES columns: column1=external_review_id, column2=author_name, column3=author_uri,
-- column4=rating, column5=text, column6=published_at.

