  ('54ca2f83-c795-5ef0-b654-07b75c71dea1', 'David Mardis', 'https://www.google.com/maps/contrib/107826988392288034964', 5.0, '', '2019-02-24 08:48:17'),
  ('8793ac52-2804-5b11-9acd-2baddefd599c', 'Josh Davisson', 'https://www.google.com/maps/contrib/100828901544211472280', 5.0, 'There is a reason Moose''s Tooth Pizza is the highest grossing pizza joint in America! Good luck trying to get a table or even take out some nights. But its always worth the wait! Don''t skip out on there brews!', '2019-02-24 02:31:16'),
  ('aba3a5d0-f751-534f-b774-0230bdbefa4d', 'Faith Carpenter', 'https://www.google.com/maps/contrib/108745288008728402695', 5.0, '', '2019-02-23 19:42:54'),
  ('0d46c44e-ddc8-551e-83f8-52cafc2d0c9f', 'TheNative44', 'https://www.google.com/maps/contrib/116404049042194879199', 5.0, '', '2019-02-23 07:28:55'),
