  ('d0023a5f-abe1-527e-9218-9a54a576bb50', 'Zelly U', 'https://www.google.com/maps/contrib/109149627633882881735', 5.0, '', '2019-02-22 20:29:37'),
  ('2e9e89c8-7610-53a6-aba6-f27e0b586c5c', 'David Besh', 'https://www.google.com/maps/contrib/109850678777738226449', 4.0, 'My roommate thinks the macaroni pizza special is the best ever.... I wasn''t impressed but I tip my hat to moose''s tooth for continuing to invent new pizzas. I really enjoy the pizza crust and atmosphere but honestly wouldn''t say this is my go-to pizza place. Too many people and Anchorage hipsters have slowly degraded this unique local restaurant into a mainstream tourist attraction. I guess it happens to the best of restaurants.', '2019-02-21 18:46:26'),
  ('147c231e-6746-5e37-9f95-c857d5ddb68f', '김은섭', 'https://www.google.com/maps/contrib/108048893457885840713', 5.0, 'Best ever ! , good price', '2019-02-21 11:44:58'),
  ('7b40b21c-8db7-5b8b-a4db-9b8f0e70d388', 'Jason Pickens', 'https://www.google.com/maps/contrib/104501905502446150491', 4.0, 'Try to get there right when it opens', '2019-02-21 08:01:48'),
  ('6ed05c5e-50bf-5af2-8f2b-a65af554551d', 'Wesley', 'https://www.google.com/maps/contrib/110945224438522544384', 5.0, 'Some of the best pizza I''ve had on my travels and a great range of beers and stout on tap,coming from Vancouvr that says a lot. Awesome staff', '2019-02-20 21:55:37'),
  ('f831cc1c-d195-56a2-a2f6-82701c5ea315', 'Savili Timo', 'https://www.google.com/maps/contrib/111685098783696147639', 5.0, 'Only con to this place is the wait time, but the wait is always worth it !! Food is super delicious. From the salads to the pizzas !', '2019-02-20 17:18:09'),
  ('88e28b6f-37ae-56c6-aeac-fbef94343030', 'a s', 'https://www.google.com/maps/contrib/104548919620238395797', 5.0, 'Anchorage almost best pizza place is rustic and seating is good', '2019-02-20 16:46:54'),
  ('53c264ca-e7a9-5ae5-9dac-6badb941af87', 'Susan williams', 'https://www.google.com/maps/contrib/114979195577635796267', 5.0, '', '2019-02-20 07:20:40'),
  ('b386c655-8601-52c4-a35a-df594edde6f5', 'Christoph Lauter', 'https://www.google.com/maps/contrib/106122699678706679027', 3.0, '', '2019-02-20 05:13:28'),
  ('70400452-cfec-58bd-acab-05ded6000280', 'Larry Shearin', 'https://www.google.com/maps/contrib/112973286386512540957', 5.0, 'Have always loved their pizza the best. In addition to their beer they brew they also make root beer (non alcoholic) and cream soda. I just tried a raspberry vinaigrette salad there last time and have to say it was great.', '2019-02-19 20:51:43')
) AS v
JOIN restaurants r ON r.google_place_id = 'pending:gmap:0x56c897b9ce6000df:0xd707e127588a8c6c'
