  ('18dac2b8-783e-5b97-8df3-6aea2a53ec60', 'Jake Tyner', 'https://www.google.com/maps/contrib/112543516643692796483', 5.0, 'Best Restaurant in Alaska', '2019-02-08 22:09:09'),
