  ('3dc5360a-d6a7-50f8-b988-3dadb3a6cdf6', 'KK HH', 'https://www.google.com/maps/contrib/108273738194920461400', 5.0, 'Very delicious pizza and service is very friendly.', '2018-10-11 16:59:55'),
