  ('0482b9c7-8f62-54d9-8525-7ed75b62c0ae', 'David Brown', 'https://www.google.com/maps/contrib/101769359460533869379', 5.0, 'We got the Santa''s Little Helper pizza. The taste was amazing. Their crust is really good.  Great sauce. Definitely recommend.  We went during the afternoon around 2pm was less busy.', '2018-10-10 18:55:53'),
  ('890d1f3e-7f4c-5f78-9a9e-63a3cfff6977', 'Randy Baxter', 'https://www.google.com/maps/contrib/100889067601358435944', 5.0, 'Great food and service.  With great company also.', '2018-10-10 14:26:49'),
