  ('7aeff627-0838-5005-93e9-d1b97a8474d1', 'Don Dubois', 'https://www.google.com/maps/contrib/103444027006937651085', 5.0, 'Likely the best pizza in anchorage. New York style thin our thick crust. Lots of pizza varieties in the standard menu options. Of course you can customize as well. Extensive local craft beer offerings. Busy but very little wait.', '2018-08-14 15:25:30'),
  ('a476a243-5a8d-5ae3-9315-d143f58ec5e3', 'Peter S', 'https://www.google.com/maps/contrib/102494341768802467925', 5.0, '', '2018-08-14 05:20:44'),
