  ('9000d460-18df-5ffe-bd9c-2576bf99c5d6', 'Harold Yutuc', 'https://www.google.com/maps/contrib/110665891801126289291', 5.0, '', '2018-08-13 20:55:30'),
  ('0a7ac714-8819-5659-8fdb-c5a098a22f97', 'Yuri Sutton', 'https://www.google.com/maps/contrib/103682291112628153287', 5.0, 'I think everyone else has said what needs to be said about this wonderful place! This is the BEST pizza place in the WORLD! The Avalanche pizza, diablo breadsticks, and the "King" wings are the go-to combo for my wife and I! The Prince William Porter is one of the best beers I have ever tasted, and the Pipeline Stout is their #2 for me. I also love their ever-rotating selection of seasonal/whatever-they''re-in-the-mood-for beers!', '2018-08-13 19:02:48'),
