  ('4d150612-9384-5ca9-9061-c8ebc8243ee9', 'Kelsey Hodnefield', 'https://www.google.com/maps/contrib/115254645551800836212', 5.0, 'Hands down, Moose''s Tooth is one of the best restaurants in Anchorage. If you vacation here this is one place you will not want to miss. Their pizza menu is as diverse as it is creative. There is something for every unique pallet. The beers on tap are superb and do not disappoint. This place is family friendly and now includes an outdoor gas fire pit, bring your pints outside and enjoy the midnight sun.', '2018-03-26 20:39:28'),
  ('f34aa149-7536-532f-bd38-50772f4397b3', 'Shelby Emmert', 'https://www.google.com/maps/contrib/117746565321685010210', 5.0, 'The best pizza I''ve ever had hands down!!!', '2018-03-26 04:43:48'),
  ('7ee7b691-82e2-5cb5-b01d-ec61c37c913f', 'John Beck', 'https://www.google.com/maps/contrib/101463643989122757518', 5.0, '', '2018-03-25 21:27:18'),
