  ('73663b00-fa62-507e-b7ec-4900313a32d4', 'Comet Python', 'https://www.google.com/maps/contrib/116949200166954079974', 5.0, 'Can''t go wrong here.', '2018-03-23 05:22:43'),
  ('bc116b2a-ef1c-5495-b0c4-eb1a3113cbbe', 'Dan Newt', 'https://www.google.com/maps/contrib/106399507844882133300', 5.0, 'Best pizza i have ever had. Sometimes I''ll take my self out on date night all alone so I can enjoy the pizza all to my self. If I had a significant other I probably still wouldn''t take her so I don''t have to share.', '2018-03-22 04:35:39'),
  ('87548574-7ddc-5ae1-b65c-52c2dfe3b97a', 'Andrea Schuster', 'https://www.google.com/maps/contrib/113604100610487884718', 5.0, 'I am not usually one to dine out on pizza, but I break that rule to go to the Moose''s Tooth. Their beer is fantastic, their pizza phenomenal. Their blackened chicken caesar salad and amazing apricot pizza (sounds weird, is actually amazing) are my go to''s. The wait can be long so make sure you have time to spare. That is quite literally the only drawback to eating here.', '2018-03-22 03:35:15'),
  ('ce761d02-8cac-54af-926f-f185a8cdc2ce', 'Mary Rora', 'https://www.google.com/maps/contrib/116763685870112077540', 5.0, 'Delicious, unique, Alaskan', '2018-03-21 17:53:52'),
