  ('8f96c020-3d28-588b-b082-26988bf64d9c', 'Blake Yuckert', 'https://www.google.com/maps/contrib/110311928160634847133', 5.0, 'Not to take the focus off of the Garlic Lovers pizza, but the wings are so good.', '2017-12-04 09:41:02'),
  ('17a4db96-de4c-5fb7-9a2e-379b41306100', 'Yagami Light', 'https://www.google.com/maps/contrib/104147611952552171514', 5.0, 'Great food nice place', '2017-12-03 02:32:46'),
