  ('792a6a19-df86-540e-9ac8-564a63988412', 'Dorn Van Dommelen', 'https://www.google.com/maps/contrib/101047355783883071699', 5.0, 'It''s a classic.', '2017-11-22 15:34:33'),
  ('f3f43d89-f60e-56af-9780-400a056bc9af', 'Boxler Family', 'https://www.google.com/maps/contrib/109708308644323576116', 5.0, '', '2017-11-21 23:54:28'),
  ('8a51ce2d-f2c3-5c74-9288-607c60f9f73b', 'Dakota Cary', 'https://www.google.com/maps/contrib/110814322601690713687', 5.0, 'Worth the flight!', '2017-11-21 21:23:10'),
  ('bd1474d3-bb77-5dc6-a1ed-7731c535966e', 'Terika Kons', 'https://www.google.com/maps/contrib/115126266795131869890', 5.0, 'Always amazing!! Avalanche pizza... one of my fav''s. Breadsticks almost just as good as the pizza''s. Creative, yummy salads. Desserts to die for & always changing. And the beers ♡♡♡ World Famous.', '2017-11-21 04:40:41'),
  ('15ba34f3-2ad8-5d24-a740-99a64f99b3ce', 'D. Kano', 'https://www.google.com/maps/contrib/117467473580646471970', 5.0, 'Who needs other pizza if you got this? Never eating dominos in Anchorage again.', '2017-11-21 02:53:14'),
  ('f604de69-5da4-5464-ab7c-997be30e2edf', 'Maggie Jones', 'https://www.google.com/maps/contrib/111967123651159641622', 4.0, '', '2017-11-20 03:16:48'),
  ('e03c4a7e-abf3-53cd-9ee2-0af0fc4557ac', 'Kenneth Elston', 'https://www.google.com/maps/contrib/109398077798633290725', 5.0, 'Being a single parent Moose''s tooth pizza amd a rebox movie has become a Friday night staple for my girls.and I for the past 3 years.  We all love the Blackened Chicken Caesar salad. If there is on thing there u should.tey is the All-Ameaican pizza and the Blackened Chicken Caesar salad', '2017-11-20 01:43:47'),
  ('2ec702d1-529a-532e-ba94-298b59fe7564', 'Dogwood Jones', 'https://www.google.com/maps/contrib/102019295763048587677', 5.0, 'Amazing pizza. Amazing atmosphere. Amazing staff. If you''re a local you already know. If you''re visiting Anchorage Moose''s Tooth is mandatory. Prepare to be here a while, it''s super busy all the time. 100% Worth the wait.', '2017-11-19 21:27:10'),
  ('5c49ac90-17b0-5246-937b-ed158ec42a62', 'Austin L', 'https://www.google.com/maps/contrib/114054100766191617281', 5.0, '', '2017-11-18 05:50:43'),
