  ('0b30da52-e177-5c13-a288-cb1f585cac73', 'Emily Rose', 'https://www.google.com/maps/contrib/114854808207626057616', 5.0, 'I love moose''s tooth. It is my go to for pizza. Anything that''s not moose''s tooth isn''t very good anymore 😅', '2017-11-16 02:12:41'),
  ('c9885020-26a5-5c80-a9dd-39960be25ef0', 'Danielle Atherton', 'https://www.google.com/maps/contrib/107746800841691447055', 5.0, '', '2017-11-15 02:38:32'),
