  ('1c351123-0ca8-522f-aeba-ad7fd2ece1b0', 'Amber Davis', 'https://www.google.com/maps/contrib/103702337755058563090', 5.0, 'Best Pizza in AK obviously 😍', '2017-10-30 04:54:24'),
  ('4cfe73d4-a542-5a6e-a835-ed4b4bc7db53', 'Justin Herrin', 'https://www.google.com/maps/contrib/109773031836753934235', 5.0, '', '2017-10-29 21:30:44'),
  ('c30e7da3-8d19-57ce-a9ed-56e9e8a8e765', 'Mark Christenson', 'https://www.google.com/maps/contrib/102120598463313964709', 5.0, 'Awesome food', '2017-10-29 04:40:56'),
  ('7e84c919-a5eb-550e-9583-04f1594ef7c2', 'Travis Johnson', 'https://www.google.com/maps/contrib/115772317159560190885', 3.0, 'Iconic, I think this might be the best ran business in town. Unfortunately the owners won''t grow it to meet demand at peak times making this primarily take out only. Get there early, don''t bring many people and plan on waiting.', '2017-10-28 04:39:36'),
  ('f2ac605d-a9b6-5234-9ada-0690a5b5cf50', 'Chris Terry', 'https://www.google.com/maps/contrib/115051086738005233006', 5.0, 'Best pizza and wings in Alaska! Great beet selection! We can''t come to Anchorage withput eating here.', '2017-10-28 01:17:30'),
  ('0ba39003-93be-5aeb-81d4-43aedfe3d83c', 'Bendik ban jr', 'https://www.google.com/maps/contrib/100735877205718654571', 5.0, 'Delicious pizza', '2017-10-27 06:35:39'),
  ('2dc01f9c-b74f-5a0c-8342-b21fe68cf361', 'Kimberly Fitzgerald', 'https://www.google.com/maps/contrib/111286939562572058184', 5.0, 'Voted Best Pizza in Alaska and is nationally recognized. Incredible pizza with lots of wheat/gluten free options. Diablo bread sticks are amazing and garlic/mozzarella pizza dough served with a spicy ranch sauce. Must try! I LOVE peanut butter pie and hands down the BEST I have ever had. Addicted and all the desserts are good but definitely try the peanut butter!', '2017-10-26 16:41:54'),
  ('cd931b3c-48d3-55b1-bbd8-0f0f4ed8d28e', 'Ian Berkland', 'https://www.google.com/maps/contrib/108614852299137562596', 5.0, '', '2017-10-26 11:26:06'),
  ('17388da4-fe8a-53de-a8b3-6612bd248ac4', 'Jason Nesslage', 'https://www.google.com/maps/contrib/113725471239558496515', 5.0, 'Excellent all around. If you''re looking up reviews, then you must be from out of state. It''s darn-right fingers-licking good!!', '2017-10-26 01:25:53'),
  ('981d4cfb-4e03-5637-8806-155471714bbb', 'Ellen Warner', 'https://www.google.com/maps/contrib/104355471212877684197', 4.0, 'Large, loud, popular, fun place for great beer and delicious pizza.  We dined at the bar, and the place was busy for the entire duration of our visit.  Despite the crowds, the service was very friendly and we were not rushed.   Great value too!', '2017-10-23 22:48:18'),
  ('2efec87a-db2d-54f4-a699-63459779c6c3', 'Collin', 'https://www.google.com/maps/contrib/100119646046373723187', 4.0, 'Large craft beer selection and good thin crust pizza.', '2017-10-23 12:43:20'),
  ('0f956f7c-7ec9-54f9-99b3-e983749e6944', 'Ryan', 'https://www.google.com/maps/contrib/113291134538397785177', 5.0, 'Best pizza, great price', '2017-10-23 07:37:51'),
