  ('9a766b00-b307-5f06-afa6-4b029447beb6', 'Jere Durbin', 'https://www.google.com/maps/contrib/105235910348513023612', 5.0, 'I haven''t been to this place once when the experience was not worth the wait. All different types of high quality pizza and beer. If ur not on a diet or looking for a cheat day better check this place out.', '2017-05-04 20:11:37'),
  ('17fc087d-f13a-5e85-8bf8-fb917696cb02', 'Mariia Tereshchenko', 'https://www.google.com/maps/contrib/101583675921203135406', 5.0, 'Pizza is awesome as usual, but their beer selection even better!', '2017-05-02 17:18:14'),
