  ('823e051d-1cc8-5643-a59d-2279b6c22f64', 'Adrianell Poteet Sorrels', 'https://www.google.com/maps/contrib/102689147616238555600', 5.0, 'Great pizza. Go at off times not around meal times and skip the wait.', '2017-04-02 16:41:11'),
