  ('db0f2a3d-75f7-5443-ab46-5b54f11fb81f', 'Kayla Hastings', 'https://www.google.com/maps/contrib/105955680333825087933', 4.0, 'Great Pizza and tasty beers', '2017-03-26 18:40:38'),
  ('1dbf8321-b79b-5656-bafa-5c77a2a2dc5a', 'Jeff Marsh', 'https://www.google.com/maps/contrib/100152194991325309136', 4.0, 'Awesome pizza', '2017-03-26 02:14:25'),
