  ('7879a33f-34c9-5091-9437-eea9ffb839f0', 'John Wilkie', 'https://www.google.com/maps/contrib/116590835331997902884', 4.0, '', '2016-07-18 17:34:37'),
  ('dbdc0c7b-3569-5d1e-a7c9-8a80b3cb3e7b', 'Spb Newgirl', 'https://www.google.com/maps/contrib/100420295515478818584', 5.0, 'You have to try this place before you leave Anchorage. One of a kind pizza and brew.', '2016-07-18 16:46:46'),
  ('b45b7742-19b9-520a-9433-75376ae61152', 'Brice Wilbanks', 'https://www.google.com/maps/contrib/105862018158110079877', 4.0, 'Great pizza of course, but slightly over hyped. Got the Chipotle Pizza and that was fantastic. I would personally limit the amount of cilantro on it just because it has a strong taste and can overpower the pizza at times. The ranch is good and creamy. Always expect a wait before being seated.', '2016-07-17 21:27:03')
) AS v
JOIN restaurants r ON r.google_place_id = 'pending:gmap:0x56c897b9ce6000df:0xd707e127588a8c6c'
WHERE true
ON CONFLICT(external_review_id) DO UPDATE SET
  restaurant_id = excluded.restaurant_id,
  author_name = excluded.author_name,
  author_uri = excluded.author_uri,
  rating = excluded.rating,
  text = excluded.text,
  published_at = excluded.published_at;

INSERT INTO reviews (restaurant_id, external_review_id, author_name, author_uri, rating, text, published_at)
SELECT r.id, v.column1, v.column2, v.column3, v.column4, v.column5, v.column6
FROM (VALUES
  ('583a9a59-0d86-51ed-ada8-cffcc7b4e86f', 'Louis', 'https://www.google.com/maps/contrib/110783275618539565513', 4.0, 'Excellent food and beer! The service left something to be desired all around, but I  was still great nonetheless. This was a great recommendation from all of the locals we talked to.', '2016-07-16 07:56:09'),
  ('71b1f40e-5bc3-58c7-8439-f9a6454652f1', 'Laurita Cottonham', 'https://www.google.com/maps/contrib/103460731318970844630', 5.0, 'The pizza is so good. Be prepared to wait approximately 15-20 minutes. It''s totally worth it. Staff is friendly.  Great atmosphere', '2016-07-13 23:21:48'),
  ('92b9c331-aa2a-5994-b0e8-990a54a69b98', 'Trevor Soderholm', 'https://www.google.com/maps/contrib/110045794586075586712', 5.0, 'If you''re in Anchorage for more than three days and you haven''t been here...you''re crazy. Best pizza around.', '2016-07-13 23:05:00'),
  ('00b69174-ed21-5b6b-bc89-80baae470859', 'José Rentería', 'https://www.google.com/maps/contrib/111933302048228888769', 3.0, 'Unnecessarily long waits. The quality of the pizza is not always consistent.', '2016-07-13 18:12:45'),
  ('967d3d27-379c-5eee-8190-9f66f3bb0d3a', 'Seth Lenzi', 'https://www.google.com/maps/contrib/110562612666627401552', 5.0, '', '2016-07-12 13:28:54'),
  ('4e58a5d9-b80e-53c0-96df-0cc7e6402f29', 'Dan Overbay', 'https://www.google.com/maps/contrib/115515460080599986308', 5.0, 'Fantastic place.  An Anchorage institution.  If you are ever in Medford, Oregon go to Kaleidoscope Pizza, you won''t be disappointed.', '2016-07-12 02:44:02'),
  ('b4aef1ab-90fa-5093-9b0d-0267ce1bf17c', 'Amy Garrett', 'https://www.google.com/maps/contrib/112467471760368527379', 5.0, '', '2016-07-11 22:05:46'),
  ('a32dcebe-4fd2-51da-b3c8-bb27e698ccf5', 'Ryan Teal', 'https://www.google.com/maps/contrib/113942573341469250003', 5.0, 'Man, the pizza here was great. We were visiting from GA and decided to grab something quick to eat. The food was great and the beer was better. Yes, you lose some of that Alaska feel by visiting a commercial  place, but the food, drinks, and people were awesome.', '2016-07-08 20:02:53'),
  ('fad4e625-8b76-57df-8fd8-36aad0b9665a', 'Far Minded', 'https://www.google.com/maps/contrib/109755201180199447452', 5.0, 'Great local pizzeria and brewed root beer and creme soda.  Don''t forget your growler', '2016-07-08 04:00:50'),
  ('84297079-c349-51c8-b936-ea1665d3afd9', 'Mattias Ahlvin', 'https://www.google.com/maps/contrib/106156902433041692968', 5.0, 'A must-visit place if you''re visiting Anchorage. Best pizza in town IMHO.', '2016-07-07 19:28:29'),
  ('ef4c8434-d032-5d72-8f4e-a7976e20a645', 'Troy Harrison', 'https://www.google.com/maps/contrib/111087560622192886241', 5.0, 'Great root beer on tap', '2016-07-05 06:50:46'),
  ('c6070bc5-2760-5d7d-aa6b-15525a3a82e4', 'Philip Ganssmann', 'https://www.google.com/maps/contrib/115740773408819787841', 4.0, 'Great Pizza and very good beer. You''ll probably have to wait a while during the "rush hour"', '2016-07-05 03:21:57'),
  ('a175b7e1-503a-5250-a30a-9c8b800b05c6', 'Brad Tombers', 'https://www.google.com/maps/contrib/102082609681953283358', 5.0, 'Owned by same people as Bear''s Tooth.  Both have pizzas with unique, flavorful combinations.  A must eat!', '2016-06-28 15:32:24'),
  ('fd558f9f-8e6b-504e-b068-c3fb364ffcdb', 'JR, Kakiko R-L', 'https://www.google.com/maps/contrib/107414724228543909310', 5.0, 'A must go place in Alaska. Mandatory pizza place. Just the best concept of pizza you will find. Variety of flavors and beer selection.', '2016-06-23 21:08:45'),
  ('3d8afb3c-1f72-5172-8e9a-d92b7ff07278', 'Marlon Lontoc', 'https://www.google.com/maps/contrib/104254011716444690373', 5.0, '', '2016-06-23 18:44:48'),
  ('284da68a-8195-5212-a29e-d4587b0ad037', 'Michal Frystacky', 'https://www.google.com/maps/contrib/113519288273089251221', 4.0, '', '2016-06-21 15:27:54'),
  ('0456c26e-ecc5-509c-9aa7-88954e55db1e', 'LORENA ZAMORA', 'https://www.google.com/maps/contrib/103280400588815989574', 5.0, 'A good Alaskan option to hang out with friends and family. The best crafted Alaska  breweries can be found here.', '2016-06-21 13:57:41'),
  ('8067af32-8053-5f9e-8ae4-a230a4ab61ac', 'Steve Parkinson', 'https://www.google.com/maps/contrib/111123156637461748444', 5.0, 'My favorite restaurant period. Amazing pizza. Great brews. Get some Diablo Sticks and a chocolate steak pizza. Santa''s Little Helper sub Denali sauce is over the top too.', '2016-06-17 16:02:30'),
  ('671fb09e-19b6-502c-a367-33e3903ba947', 'Philip Brower', 'https://www.google.com/maps/contrib/100323523556685836076', 5.0, 'It''s had a stranglehold on best restaurant in Anchorage since it opened 20 years ago for good reason!  If you love flavorless school cafeteria food, you probably not enjoy the food.  However if you love brilliant gourmet, adventurous and fun, delicious and satisfying meals?  You''ve found your new favorite eatery!  Try your next masterpiece on a wheat crust, you''ll love it!', '2016-06-13 19:19:26'),
  ('3c26c122-c9fb-5d9d-ab8c-febc4fe75cf0', 'Caleb Dyches', 'https://www.google.com/maps/contrib/100398577303602235880', 5.0, 'The Buffalo Chicken Pizza is the best!  Although every pizza that these guys make tastes awesome. The caesar salads are also the best that I''ve ever had anywhere. Great service as well.', '2016-06-13 09:24:55'),
  ('78c58351-196a-5b67-aab3-7c0086ca41d3', 'James M', 'https://www.google.com/maps/contrib/100775521124561373592', 5.0, 'Without a doubt my favorite place in Anchorage, the avalanche pizza was definitely my favorite. Do come expecting to wait though, the crowds are heavy almost always', '2016-06-11 15:35:57'),
  ('d349babf-5038-511f-9f74-58aaa224bf0c', 'amos diaz', 'https://www.google.com/maps/contrib/110959648507268476600', 5.0, '', '2016-06-09 20:49:53'),
  ('776b61f4-ce60-5e1f-9f92-959ba8b01b41', 'Angshuman Mojumder', 'https://www.google.com/maps/contrib/116461482105779988809', 4.0, 'Awesome pizza. We got the veggie and Hawaiian style pie in a fifty fifty split. The crust is there best part. While I am not a beer drinker, the better half got a sampling of four and found them rather enjoyable.', '2016-06-04 07:32:21'),
  ('60962669-8e75-5269-b1f5-745e2ef1a747', 'Ryan Bergerson', 'https://www.google.com/maps/contrib/103583403195031600123', 5.0, 'Great pizzas and draught beer', '2016-06-03 17:10:10'),
  ('d4bf0ac0-da8c-5990-b82b-2a94389e1400', 'Thomas Schaefer', 'https://www.google.com/maps/contrib/116558793918212934778', 1.0, 'Awesome pizza! Terrible service today.  I came in a group of military guys today.  The waitress tossed us the bill and made us do the work to split it.  It took our large table a long time to work out the bill.  On top of that she wanted 18% gratuity for the group which wasn''t factored in the bill so we ended up coming short causing more frustration.

What ever happened to the mooses tooth that divided the bill and ran our cards? Are those days over? Now I have to calculate a tables bill out of a long list of orders from $300 worth of charges?

Maybe my money should be spent other places that can actually serve a table of hungry military guys.', '2016-06-02 20:48:50'),
  ('981c421e-32b7-53f6-aa02-ffcb51804914', 'Alex wathogoma', 'https://www.google.com/maps/contrib/101880884419512779660', 2.0, 'I decided to go with my family to this place from reading all the good reviews. It''s also the 3rd best pizza place in the u.s. They say. The pepperoni pizza is alright but I think it''s loaded with lots of cheese and less sauce. I''ve had better pizza in places like New York. I don''t think the food is worth the wait, only thing I enjoyed was the sweet and spicy hot wings.', '2016-05-21 17:37:08'),
  ('be26b606-902d-520e-ba35-a0e51b85858b', 'Joe Mann', 'https://www.google.com/maps/contrib/109833903778781550178', 4.0, 'Amazing beer selection. The pizza was very good but I would need to explore more before committing a 5 star review.', '2016-05-18 18:49:15'),
  ('6b855ea0-3bb7-555a-aa1f-0e1f59254634', 'Tyler Oden', 'https://www.google.com/maps/contrib/100197407469340622500', 5.0, '', '2016-05-09 01:12:54'),
  ('afb0f8f7-d8fe-51ca-9aa4-5785723d128e', 'Xavier Collazo', 'https://www.google.com/maps/contrib/104294632983523228031', 4.0, 'I have mixed emotions about this place. The food usually is pretty good. But its so over hyped that no matter when you go the wait is ridiculous. They have decent beer but no liquor licence. I usually will only go for special occasions that friends have there, otherwise i avoid due to how crowded it is.', '2016-05-07 01:07:10'),
  ('5eba611f-0c8c-518d-b75f-52e98c6c5f0a', 'Austin Black', 'https://www.google.com/maps/contrib/116395517256943782328', 5.0, 'Great pizza and beer, awsome place to hangout! Definitely a must if in town! Little spendy but worth it', '2016-05-03 03:47:40'),
  ('074404de-a9a9-5e4d-86bc-6af47f91b6ed', 'Joshua Thorpe', 'https://www.google.com/maps/contrib/104933818460393173442', 5.0, 'Fantastic pizza and beer, just expect a long wait. It is worth it though', '2016-04-30 21:10:56'),
  ('c8824d8a-80b5-5e94-ad57-11c4d6ad3707', 'Mike Maltese', 'https://www.google.com/maps/contrib/110637189504625104607', 5.0, '', '2016-04-09 18:11:41'),
  ('ec9ecbe8-619b-5ca8-bfe2-5b2d5f128bdc', 'Cristina Cohen', 'https://www.google.com/maps/contrib/110297446344979825493', 3.0, '', '2016-04-05 18:07:29'),
  ('d1adde29-a9db-573e-aad6-d59991c37eab', 'Kanan St.Rose', 'https://www.google.com/maps/contrib/111593906540199018559', 5.0, 'Simply the Best Pizza!!!', '2016-03-25 20:06:06'),
  ('1679e200-e546-5f66-8520-fa8d54329f84', 'James Farr', 'https://www.google.com/maps/contrib/112069588187291001414', 5.0, 'Very good pizza, Backpacker pizza is one of my favorites. Arrive early, because you might have to wait to get a table, and sometimes you need to circle the parking lot several times to find a parking space.', '2016-03-22 20:19:43'),
  ('22442027-5184-5862-938c-0322a9082f58', 'April Bajcar', 'https://www.google.com/maps/contrib/108798507467225391714', 5.0, 'Great food and beer selection. Be prepared to wait.', '2016-03-11 06:23:23'),
  ('28f8ecf1-c965-55ff-9643-50634b9900fd', 'JD Berry', 'https://www.google.com/maps/contrib/111768384770073376961', 1.0, 'Yeah yeah everybody loves this place. The menu fine whatever on the wait. But when your bill is $19 and you pay with a 50 and get your change in 1s. That''s just plain rude. I had to go to the bar to get real change.', '2016-03-11 04:17:07'),
  ('85532e72-1943-5c30-94e7-63d5ed07c6fa', 'david brasier', 'https://www.google.com/maps/contrib/110909713615091223969', 5.0, 'Lots of beer on tap', '2016-03-03 03:50:22'),
  ('d64e18e0-e055-5a75-81a1-08636fec74cd', 'Tyler Sorensen', 'https://www.google.com/maps/contrib/116142742929537473740', 5.0, 'Best pizza in Alaska', '2016-02-28 21:24:29'),
  ('4e2dbdd4-9145-5fa0-b69e-39796495625f', 'Adam Bryant', 'https://www.google.com/maps/contrib/105924142615002698008', 5.0, 'This place is great, no argument here. It''s the best pizza in town and the beer is fantastic. Try Santa''s Little Helper or the Spicy Thai Chicken. I doubt you''ll regret it. They also have awesome concerts here during the summer (Bear Tooth takes over during the winter, as well as having its own shows).
My only problem with Moose''s Tooth is that it is SO popular. There is almost always a wait for a table, and you won''t get seated until your entire party is present. I''ve come before and been quoted 45 minutes to an hour. At that point it''s just easier to head over to the Bear Tooth!', '2016-02-17 21:24:19'),
  ('53df5ff2-093e-5524-bc0e-189196f94e59', 'Zachary Garcia', 'https://www.google.com/maps/contrib/116248841641875350443', 5.0, 'Best pizza ever. Usually ridiculously busy, but I guess that''s part of the fun. On lazy days sometimes we''ll order to-go and just go pick it up. Good beer too!', '2016-02-12 03:35:27'),
  ('39466153-4ec2-589e-bf9b-73470f75cc56', 'What The Hell', 'https://www.google.com/maps/contrib/106856031711918465094', 5.0, 'This place is cool.', '2016-01-26 15:18:53'),
  ('a647c312-19db-5602-a4d0-43699ded39b9', 'Calvin Campbell', 'https://www.google.com/maps/contrib/105313385164369521338', 5.0, 'Excellent food, drinks & staff. Therefore they are busy, so be reasonable.', '2016-01-15 17:07:20'),
  ('f3c09255-1a2d-5f81-b55e-4c19b5aaa646', 'Kevin Bennett', 'https://www.google.com/maps/contrib/105663240245593255559', 5.0, 'Best pizza in Anchorage. Period.', '2015-12-18 08:28:49'),
  ('558ae3cb-43a2-5017-9c7d-0e68d5d17ce4', 'Paul Harren', 'https://www.google.com/maps/contrib/108202505113821556156', 5.0, 'Nothing else comes close for pizza in Alaska. There''s a reason this place is always packed.

My top pizzas are Steak Chipotle and Santa''s Little Helper.', '2015-12-13 06:26:26'),
  ('a13a5d5c-08c2-5469-990f-87750a3613bc', 'Joshua Petersen', 'https://www.google.com/maps/contrib/110285889983910849307', 5.0, 'This is the best pizza you will find in Alaska! Their gourmet original pizzas are amazing! I have never taken anyone here who didn''t love it and rave about it. The Amazing Apricot, Santa''s Little Helper, and Avalanche are the three best pizzas on the menu! Diablo cheese sticks are awesome (yes they are extremely hot so be warned). The wait in the summers can be several hours so be prepared for a wait but enjoy the food once you do get in.', '2015-12-13 00:29:19'),
  ('bc5b72d6-6006-575c-8d26-cb8b2b4d5484', 'Matt B', 'https://www.google.com/maps/contrib/109477771899791335382', 5.0, 'It''s mooses tooth...it''s delicious

Monthly specials and rotating taps keep it interesting', '2015-12-02 21:57:37'),
  ('11c11dd4-810d-54e5-8f06-b89735732266', 'Kris Knox', 'https://www.google.com/maps/contrib/114892548687126764556', 5.0, '', '2015-11-29 20:09:21'),
  ('c6726b8a-2ebd-58e5-8c0f-ebcc2fc04078', 'James Massey', 'https://www.google.com/maps/contrib/101665940098252731082', 4.0, 'Such good pizza. I love the atmosphere and I love the beer. My favorite is the Northern Lights Amber. I recommend a growler of that and a wild mushroom pizza with Italian sausage!', '2015-11-22 01:29:08'),
  ('c3f3b59f-cfc7-54bb-84bc-c4e8b49a4741', 'James Kolstedt', 'https://www.google.com/maps/contrib/106470980013139317143', 5.0, 'This is a required stop if you''re visiting Alaska. If you''re coming here for dinner do expect a good wait. They have a patio area where you can hang out with your friends and a drink while you wait, so that helps the time fly by quicker.

The pizza here is the main attraction. My go-to is the Chicken Parmesan pizza. Never fails. Pair it with an apple ale and you''re all set!', '2015-11-20 19:26:15'),
  ('3523c1f0-d155-540a-b70c-c1b086283b7e', 'Tom Reale', 'https://www.google.com/maps/contrib/117749820110390509871', 5.0, 'Almost hard to over-praise the Tooth- great variety of excellent pizzas, knowledgeable and helpful staff, and they''re been doing great things with their beer brewing, especially in the last couple of years.  New varieties of IPAs and Belgians coming through the pipeline on a regular basis, and they hang onto their old favorites as well, like the  Pipeline Stout.  Only downside is that there''s almost always a wait, but you can have a beer or two while you wait, so relax and enjoy the ambiance.', '2015-11-12 18:58:55'),
  ('2e021ccc-7480-577f-99a0-9c1e21a380e1', 'Drew Cress', 'https://www.google.com/maps/contrib/101949345216512462962', 5.0, '', '2015-09-24 02:01:40'),
  ('bd6f8eae-e355-514c-ba89-315b7cc9cd7e', 'Jae', 'https://www.google.com/maps/contrib/107969996577364610418', 5.0, 'No complaints. Great pizza and great service. Worth the wait.', '2015-09-11 04:12:58'),
  ('12b6d656-21f3-53a8-b66c-439fafe5de50', 'Sean Ongley', 'https://www.google.com/maps/contrib/103113442514366021288', 5.0, '', '2015-08-04 05:55:19'),
  ('6ec5e6b0-4aa6-5ee7-987b-e42aeaa375af', 'Wuv Mydogs', 'https://www.google.com/maps/contrib/108870761235239310015', 5.0, 'Always worth the wait. Best pizza and salads! Moved out of state for 3 years and craved this all the time. Never found another place like it.', '2015-07-18 08:29:29'),
  ('00b32216-0c7d-5972-a5de-af5e3c131d29', 'Uriah Jackson', 'https://www.google.com/maps/contrib/113799665424276048717', 4.0, '', '2015-07-13 22:33:20'),
  ('c7c1615f-572c-5d86-bae7-51c982abe3ca', 'Courtney Moses', 'https://www.google.com/maps/contrib/100285083136147282292', 5.0, '', '2015-07-13 01:02:15'),
  ('8c333d8e-90f8-5bdf-b543-54059e1f685f', 'Jameson Ahern', 'https://www.google.com/maps/contrib/109379432189226582256', 5.0, 'The pizza here is how I judge all other pizza. Legendary. Their beer is outstanding as well, and if you want to try and be good, their buffalo chicken salad won''t leave you jealous of the pizza eaters around you.', '2015-06-08 01:19:11'),
  ('0ec8a0c7-3d72-531b-930a-fa1954a696fb', 'Sarah Lyle', 'https://www.google.com/maps/contrib/117695717891339639657', 5.0, 'Delicious! This is an Anchorage favorite. Everyone recommends it and I agree! We''ve been about ten different times and it doesn''t disappoint. Our favorites: spicy Thai, buffalo chicken, and brewhouse. And the raspberry wheat beer is tasty!', '2015-05-23 21:23:58'),
  ('6c2f6246-6b9d-5758-9e72-828937ba5f12', 'Mathew Evans', 'https://www.google.com/maps/contrib/101652993632600704776', 5.0, 'Best pizza and beer I have ever had.', '2015-04-07 05:05:39'),
  ('79170755-8d50-5ffd-9ea1-d539533ce0a6', 'Anthony Ervin', 'https://www.google.com/maps/contrib/100107955110305150653', 5.0, 'Our favorite pizza in all of Anchorage.  Try the Classic. You won''t be disappointed.', '2014-11-07 01:41:40'),
  ('7685aeca-949f-5d31-9454-bf43258d4d26', 'Calvin Schrage', 'https://www.google.com/maps/contrib/112263264609422591034', 5.0, '', '2014-08-05 21:56:49'),
  ('036e2a5e-8ce7-51a3-9356-11b03b20d70a', 'Van', 'https://www.google.com/maps/contrib/114688408045905452970', 4.0, 'Great Beer, Good Pizza, Always packed house, And the Korean wings are excellent!', '2014-07-16 04:33:45'),
  ('77b80eff-9d9d-5bc0-a716-0f6fc7732d96', 'Jeannette G.', 'https://www.google.com/maps/contrib/104636687373132435944', 4.0, 'Wow!  This must be the happiest place in Anchorage.  Being on lists as the best pizza in Anchorage does not hurt the Moose''s Tooth a bit.  Instead of dealing with the large crown, a take-out pizza was ordered.

From what I saw, the ambiance is great.  As for the pizza, it is quite delicious.  $20 for a medium specialty.', '2014-06-23 22:00:02'),
  ('4460b287-7be5-5323-a7fe-b7fd751a8426', 'Toni Lea Curry', 'https://www.google.com/maps/contrib/110602982954445469253', 5.0, 'Yes, there are ALWAYS long lines for this place, because it is totally worth the wait. The wild mushroom pizza (I ask for it with red sauce) is incredible. The microbrews are delicious! The salads are fresh, innovative and very good. there''s no way to go wrong with this place.', '2014-05-07 20:57:19'),
  ('1d62a835-4979-594f-8921-753887cf74dc', 'Alejandrro Echeverria', 'https://www.google.com/maps/contrib/107472654740972529102', 5.0, '', '2014-04-17 18:46:26'),
  ('997c0ed5-332f-5284-873f-0785461977c8', 'Joshua Hardy', 'https://www.google.com/maps/contrib/105382282840230977199', 5.0, 'Delicious pizza and good brewed root beer and cream soda for those who don''t drink alcohol. The only trouble is waiting in line for dinner, but the wait is worth the wait.', '2014-01-02 01:54:47'),
  ('dc075ce6-4209-50c0-9037-a02bbe54d6f7', 'Michael Lloyd', 'https://www.google.com/maps/contrib/103393428617008311806', 2.0, 'I''ve not enjoyed the food there recently. I feel like they are living off their reputation at this point. Couple that with the long wait times and it''s not worth it.', '2013-07-13 03:32:22'),
  ('0338a6d5-9557-5292-950f-f04e3765aae4', 'L Thompson', 'https://www.google.com/maps/contrib/111016039880330268234', 4.0, 'Waited at the counter 20 minutes for my take out. To add insult to the experience, I was IGNORED most of the time and had to jockey for attention, which was unprofessional. Sorry, I''m not a hot tall babe, BOYS!', '2013-05-25 06:39:15'),
